            } else if( int(amzp_shadingType) == 3 ) {
                float ds = amzp_size*2.5;
                float dd = 1. - ((d - (amzp_position/100.).z + ds/2.)/ds);
                result = float4( dd,dd,dd, 1. ) * a;
            } else if( int(amzp_shadingType) == 4 ) {
                result = float4( (n/2.)+0.5, 1. ) * a;
            } else if( int(amzp_shadingType) == 5 ) {
                float ds = amzp_size*2.5;
                float dd = 1. - ((d - (amzp_position/100.).z + ds/2.)/ds);
                result = float4( ((n/2.)+0.5)*dd, 1. ) * a;
            }
            return result;
        }
        float2 mapTexture( float2 texCoord ) {
            float texRad = amzp_texAngle * 0.0174533;
            float texCos = cos(texRad);
            float texSin = sin(texRad);
            float2x2 texRot = float2x2( texCos, -texSin, texSin, texCos );
            float texTwirlRad = amzp_texTwirl * 0.0174533;
            float texTwirlCos = cos(texTwirlRad);
            float texTwirlSin = sin(texTwirlRad);
            float2x2 texTwirlRot = float2x2( texTwirlCos, -texTwirlSin, texTwirlSin, texTwirlCos );
            float2 texScaleVec;
            texScaleVec = float2(amzp_texScale, amzp_texScale);
            texScaleVec *= float2(amzp_texStretch.x,amzp_texStretch.y);
            texCoord *= texRot;
            texCoord += amzp_texOffset / 1000.0;
            texCoord /= texScaleVec;
            if( (amzp_mirror>0.5) ) {
                texCoord = abs(mod(texCoord,2.0)-1.0);
            } else {
                texCoord = mod(texCoord, 1.);
            }
            texCoord -= 0.5;
            texCoord = texCoord * (1.-5./screen.zw);
            texCoord *= amzp_texCrop;
            texCoord *= texTwirlRot;
            texCoord += 0.5;
            return texCoord;
        }
        void amzRender(){amzVertex_main();
            float2 st = amzLayerNorm();
            st -= 0.5;
            st.x *= layer.x/layer.y;
            st /= amzp_scale;
            float3 ro = float3(0., 0., -1.);
            float3 rd = normalize(float3(st, 1.));
            float d = march(ro,rd);
            float3 p = ro + rd * d;
            float3 n = calcNormal(p);
            float3 nn = n;
            float l = lighting(p,n);
            float4 localCoord = float4(p-(amzp_position/100.), 1.);
            n = (float4(n,1.) * orientAndRotate).xyz;
            localCoord *= orientAndRotate;
            float4 pp = localCoord;
            float2 texCoord = float2(atan(pp.x,pp.z),pp.y);
            texCoord = mapTexture(texCoord);
            float4 texColor = amzTexture( 0, (float4(texCoord,0.0,1.0)*amzLayerToScreen()).xy );
            amzOutput = applyShading(texColor, p, nn, d);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
